import pyomo.environ as pyo

DATA = {
    "nodes": [0, 1, 2, 3, 4],
    "num_select": 2,
    "disp": {
        (0, 1): 20, (0, 2): 20, (0, 3): 18, (0, 4): 18,
        (1, 0): 22, (1, 2): 21, (1, 3): 16, (1, 4): 17,
        (2, 0): 16, (2, 1): 23, (2, 3): 15, (2, 4): 24,
        (3, 0): 23, (3, 1): 16, (3, 2): 23, (3, 4): 20,
        (4, 0): 19, (4, 1): 21, (4, 2): 15, (4, 3): 25,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=d["nodes"], ordered=True)
    model.P = pyo.Set(
        dimen=2,
        initialize=[(i, j) for i in d["nodes"] for j in d["nodes"] if i != j],
        ordered=True,
    )

    model.y = pyo.Var(model.N, within=pyo.Binary)
    model.z = pyo.Var(model.P, within=pyo.Binary)

    def obj_rule(m):
        return sum(d["disp"][(i, j)] * m.z[i, j] for (i, j) in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def select_rule(m):
        return sum(m.y[i] for i in m.N) == d["num_select"]

    model.select_count = pyo.Constraint(rule=select_rule)

    def link_i_rule(m, i, j):
        return m.z[i, j] <= m.y[i]

    model.link_i = pyo.Constraint(model.P, rule=link_i_rule)

    def link_j_rule(m, i, j):
        return m.z[i, j] <= m.y[j]

    model.link_j = pyo.Constraint(model.P, rule=link_j_rule)

    def link_lower_rule(m, i, j):
        return m.z[i, j] >= m.y[i] + m.y[j] - 1

    model.link_lower = pyo.Constraint(model.P, rule=link_lower_rule)

    return model
